from pathlib import Path
import json
O=Path(__file__).resolve().parents[1]
html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Z1 V5 HD — นำร่องตรวจภาพ</title>
<style>*{box-sizing:border-box}body{margin:0;background:#11151c;color:#edf0f6;font:15px system-ui,sans-serif}header{position:fixed;inset:0 0 auto;z-index:20;background:#1c222eeb;padding:12px 18px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;border-bottom:1px solid #4b5462}h1{font-size:17px;margin:0 12px 0 0}button,a{color:inherit;background:#303b4d;border:1px solid #60718b;border-radius:6px;padding:7px 12px;text-decoration:none}button[aria-pressed=true]{background:#246154;border-color:#64dabb}input[type=range]{width:150px}#viewport{position:fixed;inset:116px 0 38px;overflow:hidden;touch-action:none;cursor:grab}#viewport:active{cursor:grabbing}#world{position:absolute;left:0;top:0;width:4915px;height:3277px;transform-origin:0 0}#world img{position:absolute;pointer-events:none;user-select:none}#base{width:4915px;height:3277px}.tile{width:1024px;height:1024px}#ground,#objects,#feet,#mask{position:absolute;inset:0}#mask{width:4915px;height:3277px;opacity:.27;mix-blend-mode:screen}#feet i{position:absolute;width:8px;height:8px;background:#f7ef65;border-radius:50%;transform:translate(-50%,-50%);box-shadow:0 0 0 2px #111}footer{position:fixed;inset:auto 0 0;background:#1c222e;padding:9px 16px;font-size:12px;color:#c6d0df}#notice{flex-basis:100%;font-size:12px;color:#ffca81}.hidden{display:none!important}@media(max-width:700px){header{gap:7px;padding:8px}h1{width:100%}#viewport{top:180px}input[type=range]{width:100px}}
</style><header><h1>Z1 V5 HD · ภาพนำร่อง 4 ชิ้น</h1><button id="old" aria-pressed="false">เก่า (O)</button><button id="new" aria-pressed="true">ใหม่ (N)</button><label><input id="sprites" type="checkbox" checked> ภาพวัตถุแยก (S)</label><label><input id="foot" type="checkbox"> foot</label><label><input id="walk" type="checkbox"> walkmask ตามบรีฟ</label><label>ซูม <input id="zoom" type="range" min="0.15" max="4" step="0.01" value="0.5"></label><button id="fit">ทั้งแผนที่</button><button id="pilot">นำร่อง</button><button id="game">สเกลเกม</button><a href="README.md">README</a><div id="notice">ยังไม่ผ่านเกณฑ์รับงาน · native พื้น 1254 px / export 2048 px · ยังไม่ประกอบเข้าเกม · ลากเพื่อเลื่อน / ล้อเมาส์เพื่อซูม</div></header>
<div id="viewport"><div id="world"><img id="base" src="master-1x.jpg" alt="พื้นเดิมประกอบ repairs ทั้ง 20 ชิ้น"><div id="ground"></div><div id="objects"></div><img id="mask" class="hidden" src="inputs/walkmask-brief.png" alt="พื้นที่เดินได้จาก TOWN_WALK_RUNS"><div id="feet" class="hidden"></div></div></div><footer id="status">กำลังโหลดภาพ…</footer>
<script>
const chunks=__CHUNKS__,sprites=__SPRITES__;
const $=id=>document.getElementById(id),viewport=$('viewport'),world=$('world');let scale=.5,tx=0,ty=0,isNew=true;
for(const c of chunks){const im=new Image;im.src=c.src;im.className='tile';im.alt=c.id;im.dataset.chunk=c.id;im.style.left=c.rectPx1x[0]+'px';im.style.top=c.rectPx1x[1]+'px';$('ground').append(im)}
for(const a of sprites.sort((a,b)=>({back:0,sort:1,front:2}[a.layer]-{back:0,sort:1,front:2}[b.layer]||a.footWorld[1]-b.footWorld[1]))){const im=new Image;im.src=a.src;im.alt=a.id;im.dataset.sprite=a.id;const[x,y,w,h]=a.rectWorld;Object.assign(im.style,{left:x*4915/3840+'px',top:y*3277/2560+'px',width:w*4915/3840+'px',height:h*3277/2560+'px'});$('objects').append(im);const f=document.createElement('i');f.title=a.id+' foot '+a.footWorld.join(',');f.style.left=a.footWorld[0]*4915/3840+'px';f.style.top=a.footWorld[1]*3277/2560+'px';$('feet').append(f)}
function paint(){world.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;$('zoom').value=scale;$('status').textContent=`${isNew?'ใหม่':'เก่า'} · ซูม ${scale.toFixed(2)}× · ${(scale*4915/3840*devicePixelRatio).toFixed(2)} device px/หน่วย · วัตถุแยก ${sprites.length} ชิ้น · โหมดภาพนิ่ง`}
function mode(value){isNew=value;$('ground').classList.toggle('hidden',!value);$('objects').classList.toggle('hidden',!value||!$('sprites').checked);$('old').setAttribute('aria-pressed',!value);$('new').setAttribute('aria-pressed',value);paint()}
function center(x,y,s){scale=s;tx=viewport.clientWidth/2-x*s;ty=viewport.clientHeight/2-y*s;paint()}
function zoomAt(s,x,y){s=Math.max(.15,Math.min(4,s));const f=s/scale;tx=x-(x-tx)*f;ty=y-(y-ty)*f;scale=s;paint()}
$('old').onclick=()=>mode(false);$('new').onclick=()=>mode(true);$('sprites').onchange=()=>mode(isNew);$('foot').onchange=()=>$('feet').classList.toggle('hidden',!$('foot').checked);$('walk').onchange=()=>$('mask').classList.toggle('hidden',!$('walk').checked);
$('zoom').oninput=e=>zoomAt(+e.target.value,viewport.clientWidth/2,viewport.clientHeight/2);$('fit').onclick=()=>center(4915/2,3277/2,Math.min(viewport.clientWidth/4915,viewport.clientHeight/3277)*.96);$('pilot').onclick=()=>center(2048,2048,Math.min(viewport.clientWidth/2200,viewport.clientHeight/2200)*.96);$('game').onclick=()=>center(2450,1800,2.8/(4915/3840)/devicePixelRatio);
viewport.onwheel=e=>{e.preventDefault();const r=viewport.getBoundingClientRect();zoomAt(scale*Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top)};
let drag=null;viewport.onpointerdown=e=>{drag=[e.clientX,e.clientY,tx,ty];viewport.setPointerCapture(e.pointerId)};viewport.onpointermove=e=>{if(drag){tx=drag[2]+e.clientX-drag[0];ty=drag[3]+e.clientY-drag[1];paint()}};viewport.onpointerup=viewport.onpointercancel=()=>drag=null;
onkeydown=e=>{if(e.target.tagName==='INPUT')return;if(e.key.toLowerCase()==='o')mode(false);if(e.key.toLowerCase()==='n')mode(true);if(e.key.toLowerCase()==='s'){$('sprites').checked=!$('sprites').checked;mode(isNew)}};
Promise.all([...document.images].map(i=>i.decode().catch(()=>{$('notice').textContent+=' · โหลดไม่ได้: '+i.getAttribute('src')}))).then(()=>paint());$('pilot').click();
</script></html>'''
html=html.replace('__CHUNKS__',(O/'chunks.json').read_text()).replace('__SPRITES__',(O/'sprites.json').read_text())
(O/'index.html').write_text(html);print('Preview generated')
